import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused Residual Add + LayerNorm kernel
fused_residual_layernorm_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

// Fused residual add + LayerNorm kernel
// Input: x (attention output), residual, weight, bias
// Output: LayerNorm(x + residual)
__global__ void fused_residual_layernorm_kernel(
    const float* __restrict__ attn_out,
    const float* __restrict__ residual,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int seq_len,
    int batch_size,
    int embed_dim,
    float eps
) {
    // Each block handles one (seq, batch) pair
    int idx = blockIdx.x;
    int seq_idx = idx / batch_size;
    int batch_idx = idx % batch_size;

    if (seq_idx >= seq_len || batch_idx >= batch_size) return;

    int tid = threadIdx.x;
    int base_offset = (seq_idx * batch_size + batch_idx) * embed_dim;

    // Shared memory for reduction
    extern __shared__ float shared[];
    float* s_sum = shared;
    float* s_sum_sq = shared + blockDim.x;

    // Step 1: Compute sum and sum of squares for mean and variance
    float local_sum = 0.0f;
    float local_sum_sq = 0.0f;

    for (int i = tid; i < embed_dim; i += blockDim.x) {
        float val = attn_out[base_offset + i] + residual[base_offset + i];
        local_sum += val;
        local_sum_sq += val * val;
    }

    s_sum[tid] = local_sum;
    s_sum_sq[tid] = local_sum_sq;
    __syncthreads();

    // Reduction
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
            s_sum_sq[tid] += s_sum_sq[tid + s];
        }
        __syncthreads();
    }

    float mean = s_sum[0] / embed_dim;
    float variance = s_sum_sq[0] / embed_dim - mean * mean;
    float inv_std = rsqrtf(variance + eps);

    __syncthreads();

    // Step 2: Normalize and apply affine transformation
    for (int i = tid; i < embed_dim; i += blockDim.x) {
        float val = attn_out[base_offset + i] + residual[base_offset + i];
        float normalized = (val - mean) * inv_std;
        out[base_offset + i] = normalized * weight[i] + bias[i];
    }
}

torch::Tensor fused_residual_layernorm_hip(
    torch::Tensor attn_out,
    torch::Tensor residual,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps
) {
    // Input shape: (seq_len, batch_size, embed_dim)
    int seq_len = attn_out.size(0);
    int batch_size = attn_out.size(1);
    int embed_dim = attn_out.size(2);

    auto out = torch::empty_like(attn_out);

    int num_blocks = seq_len * batch_size;
    int block_size = 256;
    int shared_mem_size = 2 * block_size * sizeof(float);

    fused_residual_layernorm_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        attn_out.data_ptr<float>(),
        residual.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        seq_len,
        batch_size,
        embed_dim,
        eps
    );

    return out;
}
"""

fused_residual_layernorm_cpp = """
torch::Tensor fused_residual_layernorm_hip(
    torch::Tensor attn_out,
    torch::Tensor residual,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps
);
"""

fused_module = load_inline(
    name="fused_residual_layernorm",
    cpp_sources=fused_residual_layernorm_cpp,
    cuda_sources=fused_residual_layernorm_source,
    functions=["fused_residual_layernorm_hip"],
    verbose=True,
    extra_cuda_cflags=["-O3"],
)


class ModelNew(nn.Module):
    def __init__(self, embed_dim, num_heads):
        """
        Attention Block using Multihead Self-Attention with fused operations.
        :param embed_dim: Embedding dimension (the number of channels)
        :param num_heads: Number of attention heads
        """
        super(ModelNew, self).__init__()
        self.attn = nn.MultiheadAttention(embed_dim, num_heads)
        self.norm = nn.LayerNorm(embed_dim)
        self.fused_module = fused_module
        self.eps = self.norm.eps

    def forward(self, x):
        """
        Forward pass of the AttentionBlock.
        :param x: Input tensor of shape (B, C, H, W)
        :return: Output tensor of the same shape (B, C, H, W)
        """
        B, C, H, W = x.shape
        x = x.view(B, C, H * W).permute(2, 0, 1)  # (seq_len, batch_size, embed_dim)

        attn_output, _ = self.attn(x, x, x)

        # Fused residual add + LayerNorm
        x = self.fused_module.fused_residual_layernorm_hip(
            attn_output.contiguous(), 
            x.contiguous(),
            self.norm.weight,
            self.norm.bias,
            self.eps
        )

        x = x.permute(1, 2, 0).view(B, C, H, W)
        return x

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused GELU kernel
gelu_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void fused_gelu_kernel(const float* __restrict__ input, 
                                   float* __restrict__ output, 
                                   int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        // GELU: 0.5 * x * (1.0 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
        const float sqrt_2_over_pi = 0.7978845608028654f;
        float x3 = x * x * x;
        float inner = sqrt_2_over_pi * (x + 0.044715f * x3);
        output[idx] = 0.5f * x * (1.0f + tanhf(inner));
    }
}

torch::Tensor fused_gelu(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int size = input.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_gelu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size
    );

    return output;
}
"""

# Fused LayerNorm kernel
layernorm_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Warp reduction for sum
__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 32; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void layernorm_kernel(const float* __restrict__ input,
                                  const float* __restrict__ gamma,
                                  const float* __restrict__ beta,
                                  float* __restrict__ output,
                                  int batch_size,
                                  int hidden_size,
                                  float eps) {
    // Each block handles one row
    int row = blockIdx.x;
    if (row >= batch_size) return;

    const float* row_input = input + row * hidden_size;
    float* row_output = output + row * hidden_size;

    // Compute mean
    float sum = 0.0f;
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        sum += row_input[i];
    }

    // Block reduce for sum
    __shared__ float shared_sum[64];
    int lane = threadIdx.x % 64;
    int wid = threadIdx.x / 64;

    float warp_sum = warp_reduce_sum(sum);
    if (lane == 0) shared_sum[wid] = warp_sum;
    __syncthreads();

    sum = (threadIdx.x < blockDim.x / 64) ? shared_sum[threadIdx.x] : 0.0f;
    if (wid == 0) sum = warp_reduce_sum(sum);

    __shared__ float mean;
    if (threadIdx.x == 0) {
        mean = sum / hidden_size;
    }
    __syncthreads();

    // Compute variance
    float var_sum = 0.0f;
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        float diff = row_input[i] - mean;
        var_sum += diff * diff;
    }

    warp_sum = warp_reduce_sum(var_sum);
    if (lane == 0) shared_sum[wid] = warp_sum;
    __syncthreads();

    var_sum = (threadIdx.x < blockDim.x / 64) ? shared_sum[threadIdx.x] : 0.0f;
    if (wid == 0) var_sum = warp_reduce_sum(var_sum);

    __shared__ float inv_std;
    if (threadIdx.x == 0) {
        inv_std = rsqrtf(var_sum / hidden_size + eps);
    }
    __syncthreads();

    // Normalize and apply scale/shift
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        float normalized = (row_input[i] - mean) * inv_std;
        row_output[i] = gamma[i] * normalized + beta[i];
    }
}

torch::Tensor fused_layernorm(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, float eps) {
    auto sizes = input.sizes();
    int batch_size = 1;
    for (int i = 0; i < sizes.size() - 1; i++) {
        batch_size *= sizes[i];
    }
    int hidden_size = sizes[sizes.size() - 1];

    auto output = torch::empty_like(input);

    int block_size = 256;
    if (hidden_size > 256) block_size = 512;

    layernorm_kernel<<<batch_size, block_size>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        hidden_size,
        eps
    );

    return output;
}
"""

cpp_source = gelu_source + layernorm_source

custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=cpp_source,
    functions=["fused_gelu", "fused_layernorm"],
    verbose=True,
    extra_cuda_cflags=["-O3"]
)


class FusedGELU(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        return custom_ops.fused_gelu(x)


class FusedLayerNorm(nn.Module):
    def __init__(self, normalized_shape, eps=1e-5):
        super().__init__()
        self.normalized_shape = normalized_shape
        self.eps = eps
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))

    def forward(self, x):
        return custom_ops.fused_layernorm(x, self.weight, self.bias, self.eps)


class CausalSelfAttention(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.register_buffer("bias", torch.tril(torch.ones(max_seqlen, max_seqlen))
                                     .view(1, 1, max_seqlen, max_seqlen))
        self.n_head = n_head
        self.n_embd = n_embd

    def forward(self, x):
        B, T, C = x.size()

        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)

        att = (q @ k.transpose(-2, -1)) * (1.0 / math.sqrt(k.size(-1)))
        att = att.masked_fill(self.bias[:,:,:T,:T] == 0, float('-inf'))
        att = F.softmax(att, dim=-1)
        att = self.attn_dropout(att)
        y = att @ v
        y = y.transpose(1, 2).contiguous().view(B, T, C)

        y = self.resid_dropout(self.c_proj(y))
        return y


class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.ln_1 = FusedLayerNorm(n_embd)
        self.attn = CausalSelfAttention(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = FusedLayerNorm(n_embd)
        self.mlp = nn.ModuleDict(dict(
            c_fc    = nn.Linear(n_embd, 4 * n_embd),
            c_proj  = nn.Linear(4 * n_embd, n_embd),
            act     = FusedGELU(),
            dropout = nn.Dropout(resid_pdrop),
        ))
        m = self.mlp
        self.mlpf = lambda x: m.dropout(m.c_proj(m.act(m.c_fc(x))))

    def forward(self, x):
        x = x + self.attn(self.ln_1(x))
        x = x + self.mlpf(self.ln_2(x))
        return x


def custom_kernel(inputs):
    x = inputs[0]
    n_embd = 768
    n_head = 8
    attn_pdrop = 0.0
    resid_pdrop = 0.0
    max_seqlen = 1024

    model = ModelNew(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen).cuda()
    model.eval()

    with torch.no_grad():
        return model(x)

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused attention kernel: computes scaled dot-product attention with causal masking
fused_attention_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

#define BLOCK_SIZE 256

// Fused kernel: scale, causal mask, softmax in one pass using online softmax
__global__ void fused_scaled_causal_softmax_kernel(
    float* att,          // [B, nh, T, T] attention scores (will be modified in-place)
    const int B,
    const int nh,
    const int T,
    const float scale
) {
    // Each block handles one row of the attention matrix
    int batch_head_idx = blockIdx.x;  // which (batch, head) pair
    int row = blockIdx.y;             // which row in the T x T matrix

    if (batch_head_idx >= B * nh || row >= T) return;

    int b = batch_head_idx / nh;
    int h = batch_head_idx % nh;

    // Pointer to the start of this row
    float* row_ptr = att + (b * nh * T * T) + (h * T * T) + (row * T);

    // For causal attention, we only attend to positions [0, row]
    int valid_len = row + 1;

    // First pass: find max for numerical stability and apply scale
    float max_val = -INFINITY;
    for (int i = threadIdx.x; i < valid_len; i += blockDim.x) {
        float val = row_ptr[i] * scale;
        row_ptr[i] = val;  // Store scaled value back
        if (val > max_val) max_val = val;
    }

    // Reduce max across threads in block
    __shared__ float shared_max[BLOCK_SIZE];
    shared_max[threadIdx.x] = max_val;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            if (shared_max[threadIdx.x + s] > shared_max[threadIdx.x]) {
                shared_max[threadIdx.x] = shared_max[threadIdx.x + s];
            }
        }
        __syncthreads();
    }
    max_val = shared_max[0];

    // Second pass: compute exp and sum
    float sum_exp = 0.0f;
    for (int i = threadIdx.x; i < valid_len; i += blockDim.x) {
        float val = expf(row_ptr[i] - max_val);
        row_ptr[i] = val;
        sum_exp += val;
    }

    // Set masked positions to 0
    for (int i = valid_len + threadIdx.x; i < T; i += blockDim.x) {
        row_ptr[i] = 0.0f;
    }

    // Reduce sum across threads
    __shared__ float shared_sum[BLOCK_SIZE];
    shared_sum[threadIdx.x] = sum_exp;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + s];
        }
        __syncthreads();
    }
    sum_exp = shared_sum[0];

    // Third pass: normalize
    float inv_sum = 1.0f / sum_exp;
    for (int i = threadIdx.x; i < valid_len; i += blockDim.x) {
        row_ptr[i] *= inv_sum;
    }
}

torch::Tensor fused_scaled_causal_softmax(torch::Tensor att, float scale) {
    auto sizes = att.sizes();
    int B = sizes[0];
    int nh = sizes[1];
    int T = sizes[2];

    // Launch kernel: one block per (batch, head, row)
    dim3 grid(B * nh, T);
    dim3 block(BLOCK_SIZE);

    fused_scaled_causal_softmax_kernel<<<grid, block>>>(
        att.data_ptr<float>(),
        B, nh, T, scale
    );

    return att;
}
"""

fused_attention_cpp = """
torch::Tensor fused_scaled_causal_softmax(torch::Tensor att, float scale);
"""

fused_attention_module = load_inline(
    name="fused_attention",
    cpp_sources=fused_attention_cpp,
    cuda_sources=fused_attention_source,
    functions=["fused_scaled_causal_softmax"],
    verbose=True,
    extra_cuda_cflags=["-O3"]
)


class ModelNew(nn.Module):
    """
    Optimized multi-head masked self-attention with fused kernels.
    """

    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        # key, query, value projections for all heads, but in a batch
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        # output projection
        self.c_proj = nn.Linear(n_embd, n_embd)
        # regularization
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.n_head = n_head
        self.n_embd = n_embd
        self.fused_attention = fused_attention_module

    def forward(self, x):
        B, T, C = x.size()

        # calculate query, key, values for all heads in batch
        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)  # (B, nh, T, hs)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)  # (B, nh, T, hs)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)  # (B, nh, T, hs)

        # Compute Q @ K^T
        att = torch.matmul(q, k.transpose(-2, -1))  # (B, nh, T, T)

        # Fused: scale + causal mask + softmax
        scale = 1.0 / math.sqrt(k.size(-1))
        att = self.fused_attention.fused_scaled_causal_softmax(att.contiguous(), scale)

        att = self.attn_dropout(att)
        y = torch.matmul(att, v)  # (B, nh, T, T) x (B, nh, T, hs) -> (B, nh, T, hs)
        y = y.transpose(1, 2).contiguous().view(B, T, C)

        # output projection
        y = self.resid_dropout(self.c_proj(y))
        return y


def custom_kernel(inputs):
    """Entry point for wafer evaluation"""
    # Get init inputs for creating the model
    n_embd = 768
    n_head = 8
    attn_pdrop = 0.0
    resid_pdrop = 0.0
    max_seqlen = 1024

    model = ModelNew(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen).cuda()

    # Copy weights from reference if available, otherwise use random
    model.eval()

    x = inputs[0]
    with torch.no_grad():
        return model(x)

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Optimized fused kernels for attention block
fused_kernels_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

#define WARP_SIZE 64
#define BLOCK_SIZE 256

// Fused residual add + LayerNorm kernel with better memory access
__global__ void fused_residual_layernorm_kernel_v2(
    const float* __restrict__ attn_out,
    const float* __restrict__ residual,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int total_elements,
    int embed_dim,
    float eps
) {
    int idx = blockIdx.x;
    int tid = threadIdx.x;

    int base_offset = idx * embed_dim;

    // Use warp-level reductions for better performance
    float local_sum = 0.0f;
    float local_sum_sq = 0.0f;

    // Vector load if possible - process 4 elements at a time
    int i = tid;
    while (i < embed_dim) {
        float val = attn_out[base_offset + i] + residual[base_offset + i];
        local_sum += val;
        local_sum_sq += val * val;
        i += blockDim.x;
    }

    // Warp-level reduction using shuffle operations
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        local_sum += __shfl_down(local_sum, offset, WARP_SIZE);
        local_sum_sq += __shfl_down(local_sum_sq, offset, WARP_SIZE);
    }

    // Shared memory for cross-warp reduction
    __shared__ float s_sum[BLOCK_SIZE / WARP_SIZE];
    __shared__ float s_sum_sq[BLOCK_SIZE / WARP_SIZE];

    int lane = tid % WARP_SIZE;
    int warp_id = tid / WARP_SIZE;

    if (lane == 0) {
        s_sum[warp_id] = local_sum;
        s_sum_sq[warp_id] = local_sum_sq;
    }
    __syncthreads();

    // Final reduction in first warp
    if (warp_id == 0) {
        local_sum = (lane < (BLOCK_SIZE / WARP_SIZE)) ? s_sum[lane] : 0.0f;
        local_sum_sq = (lane < (BLOCK_SIZE / WARP_SIZE)) ? s_sum_sq[lane] : 0.0f;

        for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
            local_sum += __shfl_down(local_sum, offset, WARP_SIZE);
            local_sum_sq += __shfl_down(local_sum_sq, offset, WARP_SIZE);
        }
    }

    __shared__ float mean, inv_std;
    if (tid == 0) {
        mean = local_sum / embed_dim;
        float variance = local_sum_sq / embed_dim - mean * mean;
        inv_std = rsqrtf(variance + eps);
    }
    __syncthreads();

    // Apply normalization
    i = tid;
    while (i < embed_dim) {
        float val = attn_out[base_offset + i] + residual[base_offset + i];
        float normalized = (val - mean) * inv_std;
        out[base_offset + i] = normalized * weight[i] + bias[i];
        i += blockDim.x;
    }
}

torch::Tensor fused_residual_layernorm_hip(
    torch::Tensor attn_out,
    torch::Tensor residual,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps
) {
    // Input shape: (seq_len, batch_size, embed_dim)
    int seq_len = attn_out.size(0);
    int batch_size = attn_out.size(1);
    int embed_dim = attn_out.size(2);

    auto out = torch::empty_like(attn_out);

    int num_blocks = seq_len * batch_size;
    int block_size = BLOCK_SIZE;

    fused_residual_layernorm_kernel_v2<<<num_blocks, block_size>>>(
        attn_out.data_ptr<float>(),
        residual.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        num_blocks,
        embed_dim,
        eps
    );

    return out;
