class ModelNew(nn.Module):
    def __init__(self, embed_dim, num_heads):
        """
        Attention Block using optimized attention with fused operations.
        :param embed_dim: Embedding dimension (the number of channels)
        :param num_heads: Number of attention heads
        """
        super(ModelNew, self).__init__()
        self.embed_dim = embed_dim
        self.num_heads = num_heads
        self.head_dim = embed_dim // num_heads

        # Initialize projection weights similar to nn.MultiheadAttention
        self.in_proj_weight = nn.Parameter(torch.empty(3 * embed_dim, embed_dim))
        self.in_proj_bias = nn.Parameter(torch.empty(3 * embed_dim))
        self.out_proj = nn.Linear(embed_dim, embed_dim)

        self.norm = nn.LayerNorm(embed_dim)
        self.fused_module = fused_module
        self.eps = self.norm.eps

        self._reset_parameters()

    def _reset_parameters(self):
        nn.init.xavier_uniform_(self.in_proj_weight)
        nn.init.constant_(self.in_proj_bias, 0.)
        nn.init.xavier_uniform_(self.out_proj.weight)
        nn.init.constant_(self.out_proj.bias, 0.)

    def forward(self, x):
        """
        Forward pass of the AttentionBlock.
        :param x: Input tensor of shape (B, C, H, W)
        :return: Output tensor of the same shape (B, C, H, W)
        """
        B, C, H, W = x.shape
        seq_len = H * W

        # Reshape: (B, C, H, W) -> (seq_len, B, C)
        x_seq = x.view(B, C, seq_len).permute(2, 0, 1)  # (seq_len, B, C)

        # Compute Q, K, V using in_proj
        qkv = F.linear(x_seq, self.in_proj_weight, self.in_proj_bias)  # (seq_len, B, 3*C)
        qkv = qkv.view(seq_len, B, 3, self.num_heads, self.head_dim)
        qkv = qkv.permute(2, 1, 3, 0, 4)  # (3, B, num_heads, seq_len, head_dim)
        q, k, v = qkv[0], qkv[1], qkv[2]  # Each: (B, num_heads, seq_len, head_dim)

        # Use PyTorch's optimized scaled_dot_product_attention (FlashAttention)
        attn_output = F.scaled_dot_product_attention(q, k, v)  # (B, num_heads, seq_len, head_dim)

        # Reshape back
        attn_output = attn_output.permute(2, 0, 1, 3).contiguous()  # (seq_len, B, num_heads, head_dim)
        attn_output = attn_output.view(seq_len, B, C)

        # Output projection
        attn_output = self.out_proj(attn_output)

        # Fused residual add + LayerNorm
        x_norm = self.fused_module.fused_residual_layernorm_hip(
            attn_output.contiguous(), 
            x_seq.contiguous(),
            self.norm.weight,
            self.norm.bias,
            self.eps
        )

        # Reshape back: (seq_len, B, C) -> (B, C, H, W)
        out = x_norm.permute(1, 2, 0).view(B, C, H, W)

        return out

