        for (int i = idx; i < total_size && i < idx + 4; i++) {
            float x = input[i];
            const float c = 0.7978845608028654f;
            const float k = 0.044715f;
            float x3 = x * x * x;
            output[i] = 0.5f * x * (1.0f + tanhf(c * (x + k * x3)));
        }
